import {writeFile} from 'node:fs/promises';
const program=(body,extras='',imports='')=>{
 const introductory=body.includes('Hello, C#!');
 const asynchronous=/\bawait\b/.test(body);
 const source=body+'\n'+extras;
 const namespaces=['System',...(!introductory?['System.Globalization']:[])];
 if(/List<|Dictionary<|HashSet<|Queue<|Stack<|IReadOnlyList</.test(source))namespaces.push('System.Collections.Generic');
 if(/\.(Sum|Average|Min|Max|Select|Where|Any|Distinct|FirstOrDefault|GroupBy|ToList|OrderBy)/.test(source))namespaces.push('System.Linq');
 if(/\b(File|FileInfo|StreamReader|StreamWriter|IOException|InvalidDataException|Directory)\b/.test(source))namespaces.push('System.IO');
 if(/CancellationToken/.test(source))namespaces.push('System.Threading');
 if(asynchronous||/\bTask\b/.test(extras))namespaces.push('System.Threading.Tasks');
 return `${namespaces.map(n=>'using '+n+';').join('\n')}\n${imports}\nclass Program\n{\n    static ${asynchronous?'async Task':'void'} Main()\n    {\n${introductory?'':'        CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;\n'}${body.split('\n').map(l=>'        '+l).join('\n')}\n    }\n${extras}\n}\n`;
};
const starter='using System;\nclass Program\n{\n    static void Main()\n    {\n        // Write your original solution.\n    }\n}\n';
const rubric={program_functionality:25,correct_csharp:20,object_oriented_design:15,data_database_handling:10,validation_error_handling:10,code_organization_architecture:10,security:5,testing_documentation:5};
const lessons=[];
function add(title,topics,explanation,code,activity,qs,options={}) {
 const position=lessons.length+1,level=['Beginner','Intermediate','Advanced'][Math.floor((position-1)/6)];
 const quiz=qs.map(([question,correct,...wrong],i)=>{const choices=[correct,...wrong];const shift=i%choices.length;return{question,choices:[...choices.slice(shift),...choices.slice(0,shift)],answer:(choices.length-shift)%choices.length,explanation:correct+'. Review this lesson’s example and explanation.'};});
 lessons.push({title,level,position,objectives:options.objectives??[`Explain ${topics.split(';')[0].toLowerCase()} using the example.`,`Implement ${title.replace(/.*Project — /,'')} in an appropriate practice environment.`,`Validate normal and boundary inputs and document results.`],introduction:`Learn ${topics} through fictional student data and C# practice.`,explanation:explanation+'\nTopics and syntax to practice: '+topics,syntax:code,example_csharp:code,starter_csharp:starter,csharp_mode:options.mode??'console',csharp_project_guide:options.environment??'Use your own supported .NET SDK console project (prefer .NET 10 LTS). Check dotnet --list-sdks; create a C# console project, replace Program.cs, and build/run it in your authorized development environment. CodeLab only contacts a separately verified isolated provider when configured; no compiler is currently connected. Ordinary console examples use only the base class library. Database examples additionally require Microsoft.Data.Sqlite in the practice project. Keep files and database inside a dedicated disposable directory; never use CodeLab resources or credentials.',guided_practice:`1. Create a dedicated practice project; inspect the example and its expected effects.\n2. ${options.steps??'Trace the statements and identify data types, control flow, and output before running.'}\n3. Use the documented sample input (stdin one value per line). Compile in your own authorized SDK environment or the verified isolated service when available.\n4. Test normal, empty, malformed and boundary inputs; record actual compiler/runtime messages.\n5. Complete the independent activity with original source; save it and restricted project/evidence links.`,activity,expected_result:options.expected??'The program and documented tests meet the independent activity requirements; compare actual output with the example. No output is fabricated by saving source.',important_notes:options.errors??'Check spelling and case, semicolons, braces, scope, null/empty values, array bounds and type conversions. Use the first compiler error to avoid cascading diagnostics. Keep loops bounded and handle invalid input separately from unexpected failures.',debugging_tip:'Build first; inspect the first compiler diagnostic and line number. Use breakpoints or small sanitized logs, step into methods, inspect values, and reduce a failing case. Compilation errors, handled validation, runtime exceptions and sandbox timeouts mean different things. A source save or quiz pass is not proof of successful execution.',security_note:'Use fictional data and a separate disposable practice workspace. Student code must never execute on the unrestricted Laravel/Hostinger host. A connected provider must restrict processes, CPU, memory, time, output, files and network and remove its workspace afterward. Use parameterized SQL, validated inputs and resource disposal; never include CodeLab credentials or plaintext passwords in source/submissions. Desktop/web projects need their own controlled development environment.',challenge:`Summary: ${explanation.split('. ')[0]}.\nChallenge: Add one useful original improvement and a boundary/failure test; explain the relevant validation or security decision.`,completion_requirements:'Save and submit original source, program input, optional repository/project URL, and build/test evidence. Pass the five-question quiz with at least 4/5 and receive teacher approval of the current submission; projects also require rubric grading. Running alone does not complete a lesson.',quiz,validation_rules:{csharp:{test_cases:options.expected&&options.mode!=='external'?[{input:options.input??'',expected:options.expected}]:[]}},is_project:position%6===0,rubric:position%6===0?rubric:null,...(options.input?{guide:[{title:'Sample Program Input',instruction:options.input}]}:{})});
}
add('Introduction to C# and .NET','C# uses; .NET runtime; console applications; namespace; class; Main; statements; semicolons; blocks; comments',
 'C# is a statically typed language for console, web, desktop and other application development. A .NET SDK builds the program; the runtime executes compiled managed code. using imports namespace names rather than pasting a library into the program. Program is a class, Main is the entry point, braces delimit blocks and semicolons terminate many statements. This course uses an explicit Program/Main structure so beginners can see the entry point; modern top-level statements are an alternative, not required. Console.WriteLine prints a line.',
 program('Console.WriteLine("Hello, C#!");\nConsole.WriteLine("Student: Maria Santos");\nConsole.WriteLine("Course: BS Information Technology");\nConsole.WriteLine("Year: 1");\nConsole.WriteLine("School: CodeLab Practice School");'),
 'Create a console program that displays a fictional Student Name, Course, Year Level and School. Add a meaningful comment and explain namespace, class, Main and the SDK/runtime relationship.',
 [['What builds a C# project?','.NET SDK','A text file alone','Console.ReadLine','The browser textarea'],['What is the explicit entry method?','Main','WriteLine','using','Namespace'],['What does WriteLine append?','A newline','A SQL row','A password hash','A class declaration'],['What delimits a code block?','Braces','Only indentation','Quotes','A database connection'],['Where can student code run safely online?','A verified isolated service','The unrestricted Laravel host','Inside a stored text column','The production database']],
 {expected:'Hello, C#!\nStudent: Maria Santos\nCourse: BS Information Technology\nYear: 1\nSchool: CodeLab Practice School\n',objectives:['Explain the purpose of C# and its relationship to .NET.','Identify using, class, Main, statements and code blocks.','Write and run a simple C# console program in an authorized development environment.']});
add('Variables, Constants, and Data Types','declaration; assignment/reassignment; var; const; naming; int/long/double/decimal/char/bool/string; casts; Convert; Parse; TryParse',
 'Variables store typed values and can be reassigned; const values are fixed at compile time. var infers a compile-time local type from an initializer and is not dynamically typed. Use meaningful camelCase locals and PascalCase type/method names. int and long represent whole numbers; double uses binary floating point; decimal uses decimal arithmetic and needs the m suffix. char is one UTF-16 code unit, bool is true/false, and string is text. Explicit casts can narrow a value and lose information; Convert and Parse may throw on invalid or overflowing input. TryParse reports failure without using exceptions for ordinary invalid numeric input. Always validate the range after parsing.',
 program('string studentName = "Maria";\nint age = 19;\nlong studentId = 20260001L;\ndouble grade = 95.5;\ndecimal fee = 1250.50m;\nchar initial = \'M\';\nbool enrolled = true;\nvar course = "IT";\nconst decimal PassingGrade = 75m;\nage += 1;\nConsole.WriteLine($"{studentName}: age {age}; grade {grade}; fee {fee:F2}");\nConsole.WriteLine($"{studentId}; {initial}; {enrolled}; {course}; pass {PassingGrade}");'),
 'Store and display fictional student information using every listed type. Demonstrate reassignment, const, inferred/explicit types, a deliberate narrowing cast and TryParse on malformed input; explain when Convert/Parse can fail.',
 [['What does var mean?','Compile-time type inference','Any runtime type','An untyped global','A constant'],['Which literal is decimal?','1250.50m','1250.50 only','"1250.50"','true'],['What handles invalid numeric text without ordinary parsing exceptions?','TryParse','Unchecked Parse','A cast of any string','ToUpper'],['What is const?','A compile-time fixed value','A mutable collection','A database user','A loop counter keyword'],['What can a narrowing cast do?','Lose information','Always preserve every decimal place','Grant authorization','Read stdin automatically']]);
add('Input, Output, and Operators','Write/WriteLine/ReadLine; null handling; concatenation/interpolation; arithmetic; comparisons; &&/||/!; assignment; ++/--; precedence',
 'ReadLine returns text or null at end of stdin. Write does not add a newline; WriteLine does. Prefer TryParse with an explicit culture and validate the domain. Decimal arithmetic is useful for this calculator; integer division otherwise truncates toward zero. % is remainder. == compares equality while = assigns. && and || short-circuit, which lets the right side be skipped safely. Parentheses make precedence explicit. Compound assignment and increment/decrement update values; avoid overly clever expressions that hide those side effects.',
 program('Console.WriteLine("Enter first number, second number, operation (+ - * /):");\nif (!decimal.TryParse(Console.ReadLine(), NumberStyles.Number, CultureInfo.InvariantCulture, out decimal a) ||\n    !decimal.TryParse(Console.ReadLine(), NumberStyles.Number, CultureInfo.InvariantCulture, out decimal b))\n{ Console.WriteLine("Invalid numeric input"); return; }\nstring operation = Console.ReadLine() ?? "";\nif (operation == "/" && b == 0) { Console.WriteLine("Cannot divide by zero"); return; }\ntry\n{\n    decimal result = operation switch { "+" => a + b, "-" => a - b, "*" => a * b, "/" => a / b, _ => throw new ArgumentException("Unknown operation") };\n    Console.WriteLine($"Result: {result:F2}");\n}\ncatch (ArgumentException ex) { Console.WriteLine(ex.Message); }\ncatch (OverflowException) { Console.WriteLine("Result outside decimal range"); }'),
 'Build a two-number calculator that asks for an operation, uses TryParse and rejects invalid input, zero division, unknown operations and overflow. Add small comparison, remainder and compound-assignment examples.',
 [['What can ReadLine return at end of input?','null','Always zero','A Task only','A SQL row'],['What operator compares equality?','==','=','+=','++'],['What happens for integer 5 / 2?','2','2.5','3','A string'],['What should happen before dividing?','Validate the divisor','Ignore invalid input','Reset all credentials','Concatenate SQL'],['What does && do?','Short-circuit logical AND','Add integers','Compare strings with culture','Declare a constant']],
 {input:'12\n5\n/\n',expected:'Enter first number, second number, operation (+ - * /):\nResult: 2.40\n'});
add('Conditional Statements and Loops','if/else/else if; nested conditions; switch/expression; ternary; for/while/do/foreach; break/continue; nested loops; counters/accumulators',
 'Conditions select behavior and loops repeat bounded work. Classify continuous ranges, including decimal grades: 90–100 Excellent, 85 to below 90 Very Good, 80 to below 85 Good, 75 to below 80 Passed, otherwise Failed. Validate 0–100 first. foreach visits elements, for is useful for indices, while checks before a body and do checks after it. break ends a loop and continue skips the rest of the current iteration. Counters count records and accumulators total values. Nested loops multiply work; keep limits small and make progress toward termination.',
 program('decimal[] grades = {95m, 87.5m, 82m, 75m, 60m, 101m};\nint count = 0; decimal total = 0;\nforeach (decimal grade in grades)\n{\n    if (grade < 0 || grade > 100) { Console.WriteLine("Invalid grade"); continue; }\n    string band = grade >= 90 ? "Excellent" : grade >= 85 ? "Very Good" : grade >= 80 ? "Good" : grade >= 75 ? "Passed" : "Failed";\n    Console.WriteLine(band); count++; total += grade;\n}\nConsole.WriteLine($"Valid grades: {count}; total: {total:F2}");'),
 'Use a loop to process multiple grades and all five bands. Test 0, 74.9, 75, 80, 85, 89.5, 90, 100 and 101. Demonstrate for, while, do, foreach, switch, break/continue and a small bounded nested loop.',
 [['Which band includes 89.5?','Very Good','Excellent','Failed','Invalid'],['Which loop executes its body before testing?','do...while','while','foreach over empty data','for with a false condition'],['What does continue do?','Skip the rest of this iteration','Always end the program','Repeat forever','Create a new thread'],['What should precede classification?','Range validation','Deleting low grades','Disabling limits','Rounding everything upward'],['What counts records?','A counter','A namespace','A connection string','A password']],
 {expected:'Excellent\nVery Good\nGood\nPassed\nFailed\nInvalid grade\nValid grades: 5; total: 399.50\n'});
const gradeMethods=`    static decimal Average(decimal[] grades) { if (grades.Length == 0) throw new ArgumentException("At least one grade required"); return grades.Sum() / grades.Length; }
    static bool Passed(decimal average) => average >= 75m;
    static void Display(string name, decimal[] grades)
    {
        decimal average = Average(grades);
        Console.WriteLine($"Student: {name}"); Console.WriteLine($"Total: {grades.Sum():F2}");
        Console.WriteLine($"Average: {average:F2}"); Console.WriteLine($"Highest: {grades.Max():F2}; Lowest: {grades.Min():F2}");
        Console.WriteLine($"Status: {(Passed(average) ? "PASSED" : "FAILED")}");
    }`;
add('Arrays and Methods','declaration/initialization; zero-based indices; updates; Length; foreach; multidimensional arrays; parameters/arguments; returns; void; overloading; scope',
 'Arrays have fixed length and zero-based indices. new decimal[3] has valid indices 0, 1 and 2. A rectangular array uses a comma between indices and GetLength for each dimension; a jagged array contains arrays. Methods group behavior; parameters declare inputs while arguments supply values. void returns no value; a return statement supplies a result to the caller. Overloading uses different parameter lists, not return type alone. Local scope limits visibility. Validate empty arrays before averages/minimum/maximum. The example uses LINQ for brevity; implement loops yourself to practice accumulators and extrema.',
 program('decimal[] grades = {90m, 80m, 100m};\ngrades[1] = 85m;\nDisplay("Maria", grades);\nint[,] seats = {{1, 2}, {3, 4}};\nConsole.WriteLine($"Rows: {seats.GetLength(0)}");',gradeMethods),
 'Create original methods for average, highest, lowest, pass/fail and displaying results using loops. Add a void method, an overload and a small two-dimensional array. Handle empty arrays and invalid grades before calculations.',
 [['What is the last valid index of a length-3 array?','2','3','4','-1'],['What does void indicate?','No returned value','An empty class only','A decimal number','No parameters allowed'],['What distinguishes method overloads?','Parameter lists','Return type alone','Comments','Indentation'],['What must averaging guard against?','Empty arrays','Every using directive','Any return statement','All integers'],['What gives rectangular-array rows?','GetLength(0)','GetLength(1) always','Count of namespaces','Console.ReadLine']]);
const gradeProject=program('string name = (Console.ReadLine() ?? "").Trim();\nif (name.Length == 0 || name.Length > 100) { Console.WriteLine("Name required (1–100 characters)"); return; }\nif (!int.TryParse(Console.ReadLine(), out int count) || count < 1 || count > 20) { Console.WriteLine("Enter 1 to 20 grades"); return; }\ndecimal[] grades = new decimal[count];\nfor (int i = 0; i < count; i++)\n{\n    if (!decimal.TryParse(Console.ReadLine(), NumberStyles.Number, CultureInfo.InvariantCulture, out grades[i]) || grades[i] < 0 || grades[i] > 100)\n    { Console.WriteLine("Invalid grade"); return; }\n}\nDisplay(name, grades);',gradeMethods);
