const recordProject=program(`const string path = "practice-records.json";
var students = new List<Record>();
try { if (File.Exists(path)) { if (new FileInfo(path).Length > 65536) throw new InvalidDataException("File too large"); students = System.Text.Json.JsonSerializer.Deserialize<List<Record>>(File.ReadAllText(path)) ?? new(); } }
catch (Exception ex) when (ex is IOException || ex is System.Text.Json.JsonException) { Console.WriteLine("Invalid practice file; inspect it before continuing"); return; }
if (students.Any(s => s is null || !Valid(s)) || students.Select(s => s.Id).Distinct().Count() != students.Count) { Console.WriteLine("Invalid or duplicate saved records"); return; }
for (int step = 0; step < 100; step++)
{
    Console.WriteLine("1 Add | 2 View | 3 Search | 4 Edit | 5 Delete | 0 Exit");
    string choice = Console.ReadLine() ?? "0"; if (choice == "0") break;
    if (choice == "2") { foreach (var s in students) Console.WriteLine($"{s.Id}: {s.Name} ({s.Course})"); continue; }
    if (!int.TryParse(Console.ReadLine(), out int id) || id <= 0) { Console.WriteLine("Invalid ID"); continue; }
    var existing = students.FirstOrDefault(s => s.Id == id);
    if (choice == "3") { Console.WriteLine(existing is null ? "Not found" : existing.Name); continue; }
    if (choice == "5") { if (existing is not null && Console.ReadLine() == "YES") students.Remove(existing); else Console.WriteLine("Deletion not confirmed"); }
    else if (choice == "1" || choice == "4")
    {
        if ((choice == "1" && existing is not null) || (choice == "4" && existing is null)) { Console.WriteLine("Duplicate ID or record not found"); continue; }
        var record = new Record {Id=id, Name=(Console.ReadLine() ?? "").Trim(), Course=(Console.ReadLine() ?? "").Trim()};
        if (!Valid(record) || students.Count >= 100 && choice == "1") { Console.WriteLine("Invalid record or capacity reached"); continue; }
        if (existing is not null) students.Remove(existing); students.Add(record);
    }
    else { Console.WriteLine("Unknown option"); continue; }
    try { File.WriteAllText(path, System.Text.Json.JsonSerializer.Serialize(students)); } catch (IOException) { Console.WriteLine("Save failed; retry before exiting"); }
}`,`    public class Record { public int Id {get;set;} public string Name {get;set;} = ""; public string Course {get;set;} = ""; }
    static bool Valid(Record s) => s.Id > 0 && !string.IsNullOrWhiteSpace(s.Name) && s.Name.Length <= 100 && (s.Course == "IT" || s.Course == "CS");`);
add('Intermediate Project — Student Record Management System','Student objects; List<Student>; menu CRUD; validation; save/load; exceptions; delete confirmation',
 'Build a console student-record application with Add, View, Search, Edit, Delete and Exit. Use Student objects in a List, unique positive IDs, names limited to 100 characters and a documented course list. Load a bounded practice file and validate each record before use; save after successful changes and confirm deletion with YES. JSON is a safer structured alternative to a simplistic CSV split. The reference bounds capacity/menu iterations and refuses corrupt imported records; extend save-failure recovery and atomic replacement in your own design.',recordProject,
 'Milestones: define Student and menu → collection CRUD → unique-ID validation → file load/save → confirmation and exception handling → documentation. Tests: add/search/edit/delete, duplicate ID, blanks, invalid course, canceled deletion, missing/corrupt/oversized files, restart persistence and failed save. Submit original source plus practice-file schema, build instructions and actual test evidence; never submit real student data.',
 [['What ensures an edit targets the correct student?','A validated unique ID','Only array position forever','An untrusted filename','A password'],['When should deletion occur?','After explicit confirmation','On any search','Whenever input is blank','Before validation'],['What must imported records receive?','The same domain validation','Unrestricted trust','Production privileges','Only string concatenation'],['What handles multiple student objects?','List<Student>','One fixed bool','An environment secret','A namespace alias'],['What proves persistence?','Restarting and checking saved valid records','Only displaying a menu','Only a quiz pass','A fabricated console panel']],
 {environment:fileNotes,steps:'Define the class and input contract, implement one CRUD action at a time, then add persistence and validate records on load.'});
add('Advanced Collections and LINQ','List; Dictionary; HashSet; Queue; Stack; Where/Select/OrderBy/OrderByDescending/GroupBy/Any/All/Count/Sum/Average/FirstOrDefault/SingleOrDefault',
 'Choose collections by behavior: Dictionary maps keys, HashSet models uniqueness, Queue is FIFO and Stack is LIFO. LINQ transforms sequences through filtering, sorting, projection, grouping and aggregation. Most sequence pipelines defer enumeration; ToList snapshots results. Guard empty sequences before Average or use an explicit no-data result. FirstOrDefault selects at most the first match while SingleOrDefault asserts at most one and throws for duplicates. All on an empty sequence is true. Enumerable LINQ runs in memory; EF queries may translate to database SQL and have different execution costs.',
 program('var students = new[] {new Grade("Maria", "IT", 91m), new Grade("Joel", "CS", 72m), new Grade("Ana", "IT", 85m)};\nforeach (var s in students.Where(s => s.Average >= 75).OrderByDescending(s => s.Average)) Console.WriteLine($"{s.Name}: {s.Average:F2}");\nforeach (var group in students.GroupBy(s => s.Course)) Console.WriteLine($"{group.Key}: {group.Count()}");\nConsole.WriteLine($"Class average: {students.Average(s => s.Average):F2}");',`    record Grade(string Name, string Course, decimal Average);`),
 'Filter passing students, search names, sort grades, project report rows, group by course and calculate a guarded class average. Demonstrate a Dictionary, HashSet, Queue and Stack and test empty, missing and duplicate-match cases.',
 [['Which collection is FIFO?','Queue<T>','Stack<T>','HashSet<T>','Dictionary only'],['What projects values?','Select','Where only','Dispose','throw'],['What does SingleOrDefault do with two matches?','Throws','Returns both silently','Always returns null','Deletes duplicates'],['What does ToList do?','Materialize a sequence','Create a SQL permission','Hash a password','Disable evaluation'],['What needs an empty-sequence guard?','Average','ToList always','Any','Count']],
 {expected:'Maria: 91.00\nAna: 85.00\nIT: 2\nCS: 1\nClass average: 82.67\n'});
add('Generics, Delegates, and Events','generic classes/methods; type parameters/constraints; Action/Func/Predicate; event/EventArgs; publisher/subscriber',
 'Generics provide reusable compile-time type-safe components. Constraints state required type capabilities. Action returns void, Func returns a value and Predicate returns bool. A delegate represents compatible callable behavior. Events expose controlled subscription; only the publisher normally raises its declared event. EventArgs carries event data and EventHandler<T> is a conventional pattern. Unsubscribe long-lived handlers to avoid retaining objects. Subscriber exceptions can propagate; define your event failure policy rather than swallowing every error.',
 program('var service = new StudentService();\nservice.StudentAdded += (_, e) => Console.WriteLine($"Added: {e.Name}");\nAction<string> print = Console.WriteLine;\nFunc<decimal, bool> passes = grade => grade >= 75m;\nprint($"Pass: {passes(90m)}");\nservice.Add("Maria");\nvar box = new Box<int>(42); Console.WriteLine(box.Value);',`    class Box<T> { public T Value {get;} public Box(T value) {Value=value;} }
    class StudentEventArgs : EventArgs { public string Name {get;} public StudentEventArgs(string name) {Name=name;} }
    class StudentService { public event EventHandler<StudentEventArgs>? StudentAdded; public void Add(string name) { if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("Name required"); StudentAdded?.Invoke(this, new StudentEventArgs(name.Trim())); } }`),
 'Create a generic helper with an appropriate constraint and a student service that raises StudentAdded and GradeUpdated events. Use Action, Func and Predicate for small operations, subscribe/unsubscribe handlers and document subscriber error behavior.',
 [['Which delegate returns a value?','Func','Action only','void','namespace'],['What does Action return?','void','Always bool','Always int','A database connection'],['Who normally raises a declared event?','Its publisher','Any subscriber freely','The browser source textarea','The SQL parser'],['What can event data inherit?','EventArgs','Only Program','A plaintext password','A dictionary key'],['What do generic constraints state?','Required type capabilities','Runtime secrets','Output formatting only','Every possible type is identical']],
 {expected:'Pass: True\nAdded: Maria\n42\n'});
add('Asynchronous Programming','sync/async; Task/Task<T>; async/await; exceptions; CancellationToken/Source; I/O vs CPU; avoid Result/Wait',
 'async methods can suspend at await without blocking their calling thread during a genuinely asynchronous operation; async is not automatically a new thread. Task<T> represents a future result. Use async Task for operations and await exceptions in try/catch; reserve async void for framework event handlers. Cancellation is cooperative: pass the token and honor it. Avoid .Result/.Wait where blocking can deadlock or waste threads. File.ReadAllTextAsync is suitable I/O practice; Task.Delay is a simulation, not a claim of database I/O. CPU-bound work has different scheduling needs; do not wrap every I/O method in Task.Run.',
 program('using var cancellation = new CancellationTokenSource();\nConsole.WriteLine("Loading fictional records...");\ntry { string[] names = await LoadAsync(cancellation.Token); foreach (string name in names) Console.WriteLine(name); }\ncatch (OperationCanceledException) { Console.WriteLine("Loading canceled"); }',`    static async Task<string[]> LoadAsync(CancellationToken token) { await Task.Delay(25, token); token.ThrowIfCancellationRequested(); return new[] {"Maria", "Joel"}; }`),
 'Implement safe async loading with status messages, a cancellation token and exception handling. First use the deterministic simulation, then ReadAllTextAsync on a bounded practice file. Test cancellation before and during loading and explain I/O versus CPU work.',
 [['Does async automatically create a new thread?','No','Always','Only for string methods','Only with public'],['What represents an asynchronous result?','Task<T>','A plaintext file path','A namespace','A bool constant'],['What handles task exceptions normally?','await inside try/catch','Never observing the task','Empty catch everywhere','Only a comment'],['What makes cancellation work?','Operations honoring the token','Only naming a variable cancel','Deleting the database','Blocking forever'],['What is preferable for suitable I/O?','await the async API','Always call Result','Always call Wait','Spin in an infinite loop']],
 {expected:'Loading fictional records...\nMaria\nJoel\n'});
const sqliteCode=program('using var connection = new SqliteConnection("Data Source=:memory:");\nconnection.Open();\nusing (var schema = connection.CreateCommand()) { schema.CommandText = "CREATE TABLE Students(StudentId INTEGER PRIMARY KEY, Name TEXT NOT NULL, Average REAL CHECK(Average BETWEEN 0 AND 100))"; schema.ExecuteNonQuery(); }\nusing (var insert = connection.CreateCommand())\n{\n    insert.CommandText = "INSERT INTO Students(StudentId,Name,Average) VALUES(@StudentId,@Name,@Average)";\n    insert.Parameters.AddWithValue("@StudentId", 1); insert.Parameters.AddWithValue("@Name", "Maria"); insert.Parameters.AddWithValue("@Average", 91.67);\n    insert.ExecuteNonQuery();\n}\nusing var query = connection.CreateCommand();\nquery.CommandText = "SELECT StudentId,Name,Average FROM Students WHERE StudentId=@StudentId";\nquery.Parameters.AddWithValue("@StudentId", 1);\nusing var reader = query.ExecuteReader();\nwhile (reader.Read()) Console.WriteLine($"{reader.GetInt32(0)}: {reader.GetString(1)}; {reader.GetDouble(2):F2}");','','using Microsoft.Data.Sqlite;');
add('Database Programming with ADO.NET / EF Core Concepts','connections; commands/parameters; DataReader; CRUD; transactions; using/await using; ORM; DbContext/entities/DbSet; SaveChanges/Async',
 'ADO.NET separates connection, command, parameters and readers. Dispose all owned resources and use a transaction for operations that must succeed together. Parameterize values; dynamic table/column identifiers require a fixed allowlist rather than a value parameter. This example uses Microsoft.Data.Sqlite and an in-memory practice database on one open connection; it never uses CodeLab storage. Add the compatible supported NuGet package in your own practice project. EF Core maps entity types through DbContext/DbSet and tracks changes for SaveChanges or SaveChangesAsync. EF parameterization does not authorize an action: check roles and record access separately. SQLite has no native asynchronous I/O: Microsoft.Data.Sqlite async methods execute synchronously, so do not claim they make queries nonblocking. Explain EF concepts and implement ADO.NET CRUD as the baseline.',sqliteCode,
 'Implement insert/select/update/delete with parameters in an isolated SQLite database, validate input and check affected row counts. Demonstrate a transaction rollback and missing/duplicate ID handling. Sketch Student entity, DbContext, DbSet and SaveChangesAsync as an EF Core extension; list required packages/migrations and explain provider limitations.',
 [['What protects SQL values from injection?','Parameters','String concatenation','Escaping only spaces','Plaintext passwords'],['Where may a C# lab database live?','A separate disposable practice database','CodeLab production MySQL','Another student’s directory','Laravel .env'],['What groups atomic changes?','A transaction','A namespace','A public field','A comment'],['What represents an EF unit of work?','DbContext','Console.WriteLine','EventArgs','StreamWriter'],['Are Microsoft.Data.Sqlite async query methods truly asynchronous I/O?','No, they execute synchronously','Always yes','Only with a long password','Only in CodeLab']],
 {expected:'1: Maria; 91.67\n',environment:'DEPENDENCY AND ISOLATION: Create a separate C# console project with a supported .NET SDK and add Microsoft.Data.Sqlite via NuGet. Use Data Source=:memory: for this lesson. Keep the connection open while using it. Online execution requires the package already provisioned inside the isolated image; do not grant package-restore network to student runs. No production database credentials or Laravel paths are involved.'});
add('Application Architecture, Security, and Best Practices','separation of concerns; UI/services/data/models; repository; MVC; DI; interfaces; configuration; validation; SQL injection; secrets; password hashing; roles; least privilege; logging; disposal; cancellation; nullable references',
 'Separate UI input/output, service rules and data access; a repository is one possible boundary, not mandatory for every small application. MVC separates model, view and controller responsibilities; dependency injection supplies dependencies rather than hiding them in globals. Nullable reference annotations help catch null risks at build time but are not runtime authorization. Validate at service boundaries, parameterize SQL and enforce roles for every protected operation. Use a supported password-hashing mechanism with individual salts; never plaintext or fast unsalted hashes. Keep secrets out of source, logs and submissions and use a suitable configuration/secret provider; environment variables are not automatically a secure vault. Log sanitized events and dispose/cancel resources reliably.',
 program('IStudentRepository repository = new MemoryRepository();\nvar service = new StudentService(repository);\nservice.Register("Maria");\nforeach (string name in repository.List()) Console.WriteLine(name);',`    interface IStudentRepository { void Add(string name); IReadOnlyList<string> List(); }
    class MemoryRepository : IStudentRepository { private readonly List<string> names = new(); public void Add(string name) => names.Add(name); public IReadOnlyList<string> List() => names.AsReadOnly(); }
    class StudentService { private readonly IStudentRepository repository; public StudentService(IStudentRepository repository) {this.repository=repository;} public void Register(string name) {name=name.Trim(); if (name.Length == 0 || name.Length > 100) throw new ArgumentException("Valid name required"); repository.Add(name);} }`),
 'Refactor the record application into UI, Services, Data and Models. Inject an interface, validate at the service boundary, parameterize database values, dispose resources and sanitize logs. Document password hashing, server-side roles, configuration and least privilege rather than building pretend authentication.',
 [['What should a service enforce?','Business rules and protected-operation authorization','Only button visibility','No validation','Trusting client role strings'],['What supplies explicit dependencies?','Dependency injection','A plaintext password','An infinite loop','A SQL column'],['What is safe password storage?','A supported salted password-hashing mechanism','Plaintext','Unsalted SHA256 alone','Base64 only'],['Are environment variables automatically a secret vault?','No','Always','Only when uppercase','Only in a classroom'],['What should logs exclude?','Credentials and private records','All event names','All sanitized error categories','All timestamps']],
 {expected:'Maria\n'});
const sis=program(`const string database = "practice-sis.sqlite";
using var connection = new SqliteConnection($"Data Source={database}"); connection.Open();
using (var schema = connection.CreateCommand()) { schema.CommandText = "CREATE TABLE IF NOT EXISTS Users(Name TEXT PRIMARY KEY, Salt TEXT NOT NULL, Hash TEXT NOT NULL, Role TEXT CHECK(Role IN ('admin','viewer'))); CREATE TABLE IF NOT EXISTS Students(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, Course TEXT NOT NULL, Average REAL CHECK(Average BETWEEN 0 AND 100), CreatedUtc TEXT NOT NULL)"; schema.ExecuteNonQuery(); }
// Provision a practice administrator only if the users table is empty. Supply the secret outside source.
using (var count = connection.CreateCommand())
{
    count.CommandText = "SELECT COUNT(*) FROM Users";
    if (Convert.ToInt64(count.ExecuteScalar()) == 0)
    {
        string? user = Environment.GetEnvironmentVariable("PRACTICE_ADMIN_NAME");
        string? secret = Environment.GetEnvironmentVariable("PRACTICE_ADMIN_PASSWORD");
        if (string.IsNullOrWhiteSpace(user) || string.IsNullOrEmpty(secret) || secret.Length < 14) { Console.WriteLine("Provision a fictional practice admin through private configuration first"); return; }
        byte[] salt = RandomNumberGenerator.GetBytes(16); byte[] hash = Rfc2898DeriveBytes.Pbkdf2(secret, salt, 310000, HashAlgorithmName.SHA256, 32);
        using var provision = connection.CreateCommand(); provision.CommandText = "INSERT INTO Users(Name,Salt,Hash,Role) VALUES(@Name,@Salt,@Hash,'admin')";
        provision.Parameters.AddWithValue("@Name", user.Trim()); provision.Parameters.AddWithValue("@Salt", Convert.ToBase64String(salt)); provision.Parameters.AddWithValue("@Hash", Convert.ToBase64String(hash)); provision.ExecuteNonQuery();
    }
}
string? role = null;
for (int attempt = 0; attempt < 3 && role is null; attempt++)
{
    Console.WriteLine("Practice login: username then password (private stdin only)");
    string username = Console.ReadLine() ?? ""; string password = Console.ReadLine() ?? "";
    using var login = connection.CreateCommand(); login.CommandText = "SELECT Salt,Hash,Role FROM Users WHERE Name=@Name"; login.Parameters.AddWithValue("@Name", username);
    using var user = login.ExecuteReader();
    if (user.Read()) { byte[] actual = Rfc2898DeriveBytes.Pbkdf2(password, Convert.FromBase64String(user.GetString(0)), 310000, HashAlgorithmName.SHA256, 32); if (CryptographicOperations.FixedTimeEquals(actual, Convert.FromBase64String(user.GetString(1)))) role = user.GetString(2); }
    if (role is null) Console.WriteLine("Invalid credentials");
}
if (role is null) return;
for (int action = 0; action < 100; action++)
{
    Console.WriteLine("1 Dashboard | 2 List/report | 3 Search | 4 Add | 5 Edit | 6 Delete | 0 Logout");
    string choice = Console.ReadLine() ?? "0"; if (choice == "0") { role = null; Console.WriteLine("Logged out"); break; }
    if (choice == "1")
    {
        using var summary = connection.CreateCommand(); summary.CommandText = "SELECT COUNT(*),COALESCE(SUM(CASE WHEN Average>=75 THEN 1 ELSE 0 END),0) FROM Students";
        using var rows = summary.ExecuteReader(); if (rows.Read()) Console.WriteLine($"Total: {rows.GetInt32(0)}; passing: {rows.GetInt32(1)}; failing: {rows.GetInt32(0)-rows.GetInt32(1)}"); continue;
    }
    if (choice == "2" || choice == "3")
    {
        using var report = connection.CreateCommand();
        report.CommandText = choice == "2" ? "SELECT Id,Name,Course,Average FROM Students ORDER BY Average DESC,Id LIMIT 100" : "SELECT Id,Name,Course,Average FROM Students WHERE instr(lower(Name),lower(@Search))>0 ORDER BY Id LIMIT 100";
        if (choice == "3") report.Parameters.AddWithValue("@Search", (Console.ReadLine() ?? "").Trim());
        using var rows = report.ExecuteReader(); while (rows.Read()) Console.WriteLine($"{rows.GetInt32(0)}: {rows.GetString(1)} ({rows.GetString(2)}) {rows.GetDouble(3):F2}"); continue;
    }
    if (role != "admin") { Console.WriteLine("Admin role required"); continue; }
    if (choice != "4" && choice != "5" && choice != "6") { Console.WriteLine("Unknown option"); continue; }
    if (!int.TryParse(Console.ReadLine(), out int id) || id <= 0) { Console.WriteLine("Invalid ID"); continue; }
    using var command = connection.CreateCommand(); command.Parameters.AddWithValue("@Id", id);
    if (choice == "6") { if (Console.ReadLine() != "YES") { Console.WriteLine("Deletion canceled"); continue; } command.CommandText = "DELETE FROM Students WHERE Id=@Id"; }
    else
    {
        string name = (Console.ReadLine() ?? "").Trim(); string course = (Console.ReadLine() ?? "").Trim();
        if (name.Length == 0 || name.Length > 100 || (course != "IT" && course != "CS") || !double.TryParse(Console.ReadLine(), NumberStyles.Float, CultureInfo.InvariantCulture, out double average) || !double.IsFinite(average) || average < 0 || average > 100) { Console.WriteLine("Invalid student record"); continue; }
        command.Parameters.AddWithValue("@Name", name); command.Parameters.AddWithValue("@Course", course); command.Parameters.AddWithValue("@Average", average);
        command.CommandText = choice == "4" ? "INSERT INTO Students(Id,Name,Course,Average,CreatedUtc) VALUES(@Id,@Name,@Course,@Average,@Created)" : "UPDATE Students SET Name=@Name,Course=@Course,Average=@Average WHERE Id=@Id";
        if (choice == "4") command.Parameters.AddWithValue("@Created", DateTime.UtcNow.ToString("O"));
    }
    try { Console.WriteLine($"Affected: {command.ExecuteNonQuery()}"); } catch (SqliteException) { Console.WriteLine("Database change failed; check ID and practice constraints"); }
}
await Task.CompletedTask;`,'','using Microsoft.Data.Sqlite;\nusing System.Security.Cryptography;');
add('Advanced Project — C# Student Information System','authentication/logout/roles; dashboard; student CRUD; reports; OOP/interfaces; LINQ; async; isolated SQLite; architecture; security',
 'Build a learner-owned console application as the baseline; desktop or ASP.NET Core is an optional external mode. The reference is a deliberately small console foundation with hashed practice-admin provisioning, login/logout, role checks, summary, listing/filtering/sorting, validated CRUD, delete confirmation and parameterized SQLite. It is not production identity software. Environment configuration is private and must never be included in CodeLab source/stdin/evidence. The fixed PBKDF2 parameters demonstrate salted slow hashing; a real deployment should use a supported identity/password hasher with versioned parameters, rate limits across sessions and a reviewed current policy. The reference login attempts bound a single process, not a production distributed rate limit. Students must refactor it into focused Models/UI/Services/Data, add a viewer provisioning workflow under admin authorization, extend course/recent-student reports, LINQ in service reports and appropriate async file/report loading with cancellation. Microsoft.Data.Sqlite queries remain synchronous. Password input here is for private local practice; do not save credential-bearing stdin in CodeLab. For a web option use ASP.NET Core Identity/authorization and HTTPS, not this console login as a web auth system.',sis,
 'Required milestones: choose console/desktop/ASP.NET mode → define Student/User models and interfaces → isolate practice database → parameterized repository CRUD → validated services → supported salted password hashing and authorized role provisioning → login/logout → dashboard totals/course counts/passing/failing/recent records → reports/filter/sort → async I/O where appropriate → sanitized errors/logs → tests/documentation. Suggested schema: Students(Id,Name,Course,Average,CreatedUtc), Users(Name,Salt,Hash,Role), with unique IDs and role/grade constraints; do not use production data. Checklist: duplicate/missing IDs, invalid grades/names/course, canceled deletion, viewer CRUD denied at service layer, wrong password, logout protection, injection-like names, database failure, cancellation, empty reports and restart persistence. Submit original complete project source via restricted repository link, schema/build steps and sanitized screenshots/tests, excluding credentials/database with user hashes/private records.',
 [['Where should authorization be enforced?','Each protected service operation','Only hiding menu choices','Only trusting role input','Only in CSS'],['What may project evidence contain?','Sanitized build and test results','Private passwords','Production database credentials','Another student’s records'],['What must the learner add beyond the foundation?','Focused architecture and documented required extensions','A fake Run output','Unrestricted host access','Plaintext passwords'],['Which database is appropriate?','An isolated practice SQLite database','CodeLab production database','A shared admin database without limits','Laravel users directly'],['What does logout do?','Remove the active session authorization','Delete every student','Expose the hash','Grant admin access']],
 {mode:'external',environment:'EXTERNAL COMPLETE PROJECT: Build in your own controlled .NET SDK console project and add Microsoft.Data.Sqlite via NuGet. Use a dedicated practice folder and practice-sis.sqlite; never the CodeLab database. Provision fictional admin credentials privately through PRACTICE_ADMIN_NAME and PRACTICE_ADMIN_PASSWORD outside source. Do not save passwords in the CodeLab Program Input field. Online one-shot runs do not model durable login sessions or persistent databases. Desktop mode requires Windows/Visual Studio; ASP.NET Core requires its own controlled web host and supported Identity configuration. CodeLab stores source/project links and teacher-reviewed evidence only.',expected:'Actual learner environment demonstrates login/logout and enforced roles, summary reports, validated student CRUD, isolated persistence, organized service/repository classes, LINQ reports and appropriate cancelable async I/O. The reference is a foundation; required extensions and security tests must be demonstrated in the submitted project.'});
